var api = Engine.get_singleton("AutopilotTools")
if api == null:
	return {"ok": false, "note": "AutopilotTools singleton not registered"}
var removed = 0
for tool_name in api.list_tools():
	var info = api.get_tool(str(tool_name))
	var handle = int(info.get("handle", 0))
	if handle > 0 and api.unregister_tool(handle):
		removed += 1
api.set_enabled(false)
return {"ok": true, "removed": removed, "enabled": api.is_enabled()}

