func _run():
	var api = Engine.get_singleton('AutopilotTools')
	var removed = false
	if api != null:
		var info = api.get_tool('user_rescan_probe')
		var handle = int(info.get('handle', -1))
		if handle > 0:
			removed = api.unregister_tool(handle)
	var file_err = DirAccess.remove_absolute('res://gda_tmp_user_tools/probe_tool.gd')
	var dir_err = DirAccess.remove_absolute('res://gda_tmp_user_tools')
	return {'removed': removed, 'file_err': file_err, 'dir_err': dir_err}
